edits.old:
case KEY_ENTER:
    if (curr_file_id >= 0 && curr_file_id < num_itr_files) {
        Treplay_post *post = &itr_file_list[curr_file_id];
        if (post->directory) {
            strcpy(path, post->full_path);
            canonicalize_filename(fname, path, sizeof(fname));
            strcpy(path, fname);
            update_file_list(path);
            curr_file_id = offset = 0;
            need_to_update = 1;
        } else if (rep) {
            play_menu_select();
            done = 1;
        }
    }
    break;
case KEY_DEL:
    if (curr_file_id >= 0 && curr_file_id < num_itr_files &&
        !itr_file_list[curr_file_id].directory && rep &&
        my_alert("Really delete replay?", "WARNING: It will be gone forever.",
                 1, 0)) {
        delete_file(itr_file_list[curr_file_id].full_path);
        need_to_update = 1;
    }
    break;
case KEY_ESC:
    play_menu_select();
    destroy_replay(rep);
    rep = NULL;
    done = -1;
    break;
case KEY_F1:
    set_sort_method(1);
    need_to_update = 1;
    break;
case KEY_F2:
    set_sort_method(2);
    need_to_update = 1;
    break;
case KEY_F3:
    set_sort_method(3);
    need_to_update = 1;
    break;
case KEY_F4:
    set_sort_method(4);
    need_to_update = 1;
    break;
case KEY_F5:
    install_mouse();
    file_select_ex("Select a new folder and press OK", path, "itr",
                   sizeof(fname), 400, 400);
    remove_mouse();
    replace_filename(fname, path, "", sizeof(fname));
    strcpy(path, fname);
    update_file_list(path);
    curr_file_id = offset = 0;
    need_to_update = 1;
    ok_to_rename = 1;
    break;

edits.new:
case KEY_F1: {
    char p[1024];

    play_menu_select();
    if (rep)
        destroy_replay(rep);
    gui_bg_color = makecol(255, 255, 255);
    gui_fg_color = makecol(0, 0, 0);
    install_mouse();
    file_select_ex("Select a new folder and press OK.", path, "itr",
                   sizeof(p), 400, 400);
    remove_mouse();
    replace_filename(p, path, "", sizeof(p));
    strcpy(path, p);
    need_to_update = 1;
    offset = 0;
    curr_file_id = 0;
    break;
}
case KEY_DEL:
    if (curr_file_id >= 0 && curr_file_id < num_itr_files &&
        !itr_file_list[curr_file_id].directory && rep) {
        play_menu_select();
        strcpy(fname, "Really delete replay?");
        if (my_alert(fname, "WARNING: It will be gone forever.", 1, 0)) {
            delete_file(itr_file_list[curr_file_id].full_path);
            need_to_update = 1;
        }
    }
    break;
case KEY_ESC:
    play_menu_select();
    destroy_replay(rep);
    rep = NULL;
    done = -1;
    break;
case KEY_ENTER:
case KEY_SPACE:
    if (curr_file_id >= 0 && curr_file_id < num_itr_files) {
        Treplay_post *post = &itr_file_list[curr_file_id];
        if (post->directory) {
            strcpy(path, post->full_path);
            canonicalize_filename(fname, path, sizeof(fname));
            strcpy(path, fname);
            update_file_list(path);
            curr_file_id = offset = 0;
            need_to_update = 1;
        } else if (rep) {
            play_menu_select();
            done = 1;
        }
    }
    break;
